async def act(page):
    """
    Navigate from the current homepage state to the requested post and leave the
    comment: 'Well written and easy to understand.'

    Strategy (step-by-step):
    1) Dismiss any visible popup that might block interactions by scanning
       accessible buttons for names like 'close', '×' or similar.
    2) Use the complementary region's search widget (accessed via
       page.get_by_role("complementary")) to search for a distinctive keyword
       that should locate the requested post.
    3) Inspect the resulting <main> article list to find a post whose title
       matches the target (exact match preferred, otherwise substring match
       on keywords like 'rivalries' or 'murdoch').
    4) Navigate to the post URL (relative goto allowed).
    5) In the post page's main region, find the comment textbox and fill the
       requested comment. Attempt to fill name/email fields if present.
    6) Find and click a submit button inside the main region (use full
       get_by_role path where possible).

    Notes about the knowledge-base helpers: the natural helper for performing a
    visible search (create_curated_collection_by_search) is disabled in this
    environment, so this implementation performs the search and scraping via
    accessibility-role-centric selectors directly.
    """
    import asyncio

    target_full_title = (
        "Rivalries And Rumours: How The New Order Of The Murdoch Dynasty Is Playing Out"
    )
    comment_text = "Well written and easy to understand."
    search_keyword = "Rivalries Murdoch"

    async def safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    # 1) Try to dismiss any obvious popup by scanning page-level buttons for a close affordance
    try:
        all_buttons = page.get_by_role("button")
        btn_count = await safe_count(all_buttons)
        for i in range(btn_count):
            btn = all_buttons.nth(i)
            name = ""
            aria = None
            try:
                aria = await btn.get_attribute("aria-label")
            except Exception:
                aria = None
            try:
                name_text = (await btn.inner_text()).strip()
            except Exception:
                name_text = ""
            if aria:
                name = aria.strip()
            elif name_text:
                name = name_text
            # heuristic checks for close-like buttons
            if name:
                low = name.lower()
                if "close" in low or low in ("×", "x", "✕") or low.startswith("close"):
                    try:
                        await btn.click()
                        # give UI a moment to settle after dismiss
                        await asyncio.sleep(0.25)
                        break
                    except Exception:
                        # ignore click failure and continue scanning
                        pass
    except Exception:
        # non-fatal; continue even if popup cannot be dismissed
        pass

    # 2) Use the complementary region's search widget
    comp = page.get_by_role("complementary")
    comp_count = await safe_count(comp)
    if comp_count == 0:
        # If no complementary region, fall back to page-level searchbox
        searchbox = page.get_by_role("searchbox")
    else:
        # prefer first complementary region
        comp_region = comp.first
        # try canonical searchbox labelled 'Search'
        searchbox = comp_region.get_by_role("searchbox", name="Search")
        if await safe_count(searchbox) == 0:
            # fallback to any searchbox inside complementary
            searchbox = comp_region.get_by_role("searchbox")
        if await safe_count(searchbox) == 0:
            # fallback to a textbox inside complementary
            searchbox = comp_region.get_by_role("textbox")

    if await safe_count(searchbox) == 0:
        # As a final fallback try a page-level searchbox or textbox
        searchbox = page.get_by_role("searchbox")
        if await safe_count(searchbox) == 0:
            searchbox = page.get_by_role("textbox")

    if await safe_count(searchbox) == 0:
        raise Exception("No search input found on the page to locate the target post")

    # Fill the search and submit using the complementary region's Search button when available
    try:
        await searchbox.first.fill(search_keyword)
    except Exception:
        # if fill fails, continue; maybe input is already filled
        pass

    submitted_search = False
    if comp_count > 0:
        comp_region = comp.first
        search_btn = comp_region.get_by_role("button", name="Search")
        if await safe_count(search_btn) > 0:
            try:
                await search_btn.first.click()
                submitted_search = True
            except Exception:
                # try pressing Enter in the searchbox as a fallback
                try:
                    await searchbox.first.press("Enter")
                    submitted_search = True
                except Exception:
                    pass
    if not submitted_search:
        # fallback: press Enter in the located searchbox
        try:
            await searchbox.first.press("Enter")
            submitted_search = True
        except Exception:
            pass

    if not submitted_search:
        raise Exception("Failed to submit the search query")

    # Wait for the results to appear in main (or networkidle)
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle", timeout=4000)
        except Exception:
            # give a tiny grace period
            await asyncio.sleep(0.5)

    # 3) Inspect articles in main for the target
    main = page.get_by_role("main")
    if await safe_count(main) == 0:
        raise Exception("Search did not produce a visible main region with articles")

    articles = main.get_by_role("article")
    n_articles = await safe_count(articles)
    found_post_href = None

    for i in range(n_articles):
        article = articles.nth(i)
        # Prefer heading -> link
        heading = article.get_by_role("heading")
        if await safe_count(heading) > 0:
            # first link inside heading
            try:
                heading_link = heading.first.get_by_role("link")
                if await safe_count(heading_link) > 0:
                    try:
                        title_text = (await heading_link.first.inner_text()).strip()
                    except Exception:
                        title_text = ""
                    low = title_text.lower() if title_text else ""
                    if title_text and (
                        title_text.strip().lower() == target_full_title.strip().lower()
                        or "rivalries" in low
                        or "murdoch" in low
                    ):
                        try:
                            href = await heading_link.first.get_attribute("href")
                        except Exception:
                            href = None
                        if href:
                            found_post_href = href
                            break
            except Exception:
                pass
        # fallback: first link inside article
        try:
            first_link = article.get_by_role("link")
            if await safe_count(first_link) > 0:
                try:
                    link_text = (await first_link.first.inner_text()).strip()
                except Exception:
                    link_text = ""
                low = link_text.lower() if link_text else ""
                if link_text and (
                    link_text.strip().lower() == target_full_title.strip().lower()
                    or "rivalries" in low
                    or "murdoch" in low
                ):
                    try:
                        href = await first_link.first.get_attribute("href")
                    except Exception:
                        href = None
                    if href:
                        found_post_href = href
                        break
        except Exception:
            pass

    if not found_post_href:
        raise Exception("Could not locate the target post in the search results")

    # 4) Navigate to the discovered post URL (relative goto allowed)
    await page.goto(found_post_href)

    # Wait for the post page to settle
    try:
        await page.get_by_role("main").wait_for(timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle", timeout=4000)
        except Exception:
            await asyncio.sleep(0.5)

    # 5) Find the comment textbox inside the post's main region and fill the comment
    post_main = page.get_by_role("main")
    # Prefer labelled comment box
    comment_locator = post_main.get_by_role("textbox", name="Comment")
    if await safe_count(comment_locator) == 0:
        comment_locator = post_main.get_by_role("textbox", name="Leave a Comment")
    if await safe_count(comment_locator) == 0:
        # any textbox inside post main
        comment_locator = post_main.get_by_role("textbox")
    if await safe_count(comment_locator) == 0:
        # page-level fallback
        comment_locator = page.get_by_role("textbox")

    if await safe_count(comment_locator) == 0:
        raise Exception("No textbox found on the post page to enter the comment")

    tb_count = await safe_count(comment_locator)
    comment_box = comment_locator.nth(max(0, tb_count - 1))
    await comment_box.fill(comment_text)

    # 5b) Attempt to fill name/email if present
    name_labels = ["Name", "Your name", "Author", "Nickname", "Your Name"]
    email_labels = ["Email", "Your email", "Email address", "Your Email"]

    for lbl in name_labels:
        loc = post_main.get_by_role("textbox", name=lbl)
        if await safe_count(loc) > 0:
            try:
                await loc.first.fill("Commenter")
            except Exception:
                pass
            break
    else:
        for lbl in name_labels:
            loc = page.get_by_role("textbox", name=lbl)
            if await safe_count(loc) > 0:
                try:
                    await loc.first.fill("Commenter")
                except Exception:
                    pass
                break

    for lbl in email_labels:
        loc = post_main.get_by_role("textbox", name=lbl)
        if await safe_count(loc) > 0:
            try:
                await loc.first.fill("commenter@example.com")
            except Exception:
                pass
            break
    else:
        for lbl in email_labels:
            loc = page.get_by_role("textbox", name=lbl)
            if await safe_count(loc) > 0:
                try:
                    await loc.first.fill("commenter@example.com")
                except Exception:
                    pass
                break

    # 6) Find and click a submit button inside the post main region using full get_by_role path
    candidate_button_names = [
        "Post Comment",
        "Submit Comment",
        "Submit",
        "Comment",
        "Send",
        "Send Comment",
        "Post",
        "Leave a Comment",
        "Post Comment"
    ]

    clicked = False
    for name in candidate_button_names:
        btn = post_main.get_by_role("button", name=name)
        if await safe_count(btn) > 0:
            try:
                await btn.first.click()
                clicked = True
                break
            except Exception:
                pass

    if not clicked:
        # fallback to the first button inside main
        main_buttons = post_main.get_by_role("button")
        if await safe_count(main_buttons) > 0:
            try:
                await main_buttons.first.click()
                clicked = True
            except Exception:
                pass

    if not clicked:
        # page-level fallback: click the first button on the page
        page_buttons = page.get_by_role("button")
        if await safe_count(page_buttons) > 0:
            try:
                await page_buttons.first.click()
                clicked = True
            except Exception:
                pass

    if not clicked:
        raise Exception("Could not find a button to submit the comment")

    # Wait a short moment for submission processing
    try:
        await page.wait_for_load_state("networkidle", timeout=5000)
    except Exception:
        await asyncio.sleep(1)

    # Completed the task: comment entered and submit clicked

